using System.Security.Cryptography;

namespace Fugue.Domain.Ids;

/// <summary>
/// UUID version 7 (RFC 9562): a 48-bit unix-millisecond timestamp followed by random bits, so ids sort by creation
/// time and keep B-tree inserts append-mostly. .NET 8 has no <c>Guid.CreateVersion7</c>, hence this utility.
/// Ids generated by one process are strictly increasing, even within the same millisecond (a 12-bit counter in
/// <c>rand_a</c>, RFC 9562 section 6.2 method 1). Byte order is big-endian, which is also Postgres' <c>uuid</c> ordering.
/// </summary>
public static class Uuid7
{
    private const int CounterMax = 0xFFF;

    private static readonly object Gate = new();
    private static long _lastMilliseconds = -1;
    private static int _counter;

    public static Guid NewGuid() => NewGuid(TimeProvider.System);

    public static Guid NewGuid(TimeProvider time)
    {
        ArgumentNullException.ThrowIfNull(time);
        long milliseconds = time.GetUtcNow().ToUnixTimeMilliseconds();
        int counter;
        lock (Gate)
        {
            if (milliseconds > _lastMilliseconds)
            {
                _lastMilliseconds = milliseconds;
                _counter = RandomNumberGenerator.GetInt32(0, 0x800); // leave headroom so the counter rarely overflows
            }
            else
            {
                _counter++;
                if (_counter > CounterMax)
                {
                    _lastMilliseconds++;
                    _counter = 0;
                }
            }

            milliseconds = _lastMilliseconds;
            counter = _counter;
        }

        Span<byte> bytes = stackalloc byte[16];
        bytes[0] = (byte)(milliseconds >> 40);
        bytes[1] = (byte)(milliseconds >> 32);
        bytes[2] = (byte)(milliseconds >> 24);
        bytes[3] = (byte)(milliseconds >> 16);
        bytes[4] = (byte)(milliseconds >> 8);
        bytes[5] = (byte)milliseconds;
        bytes[6] = (byte)(0x70 | (counter >> 8));
        bytes[7] = (byte)counter;
        RandomNumberGenerator.Fill(bytes[8..]);
        bytes[8] = (byte)((bytes[8] & 0x3F) | 0x80); // RFC 4122 variant

        return new Guid(bytes, bigEndian: true);
    }

    /// <summary>The embedded unix-millisecond timestamp, for tests and diagnostics.</summary>
    public static DateTimeOffset Timestamp(Guid id)
    {
        Span<byte> bytes = stackalloc byte[16];
        id.TryWriteBytes(bytes, bigEndian: true, out _);
        long milliseconds = ((long)bytes[0] << 40) | ((long)bytes[1] << 32) | ((long)bytes[2] << 24)
            | ((long)bytes[3] << 16) | ((long)bytes[4] << 8) | bytes[5];
        return DateTimeOffset.FromUnixTimeMilliseconds(milliseconds);
    }
}
